from collections import defaultdict

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.
    """
    # Split the input string into individual words and count occurrences
    words = test.split()
    if not words:
        return {}

    # Initialize a dictionary to count occurrences of each letter
    letter_counts = defaultdict(int)
    max_count = 0
    result = {}

    for word in words:
        letter_counts[word] += 1

    # Find the maximum count of any letter occurrence
    for letter, count in letter_counts.items():
        if count > max_count:
            max_count = count

    # Build the result dictionary containing only letters with the maximum count
    for letter, count in letter_counts.items():
        if count == max_count:
            result[letter] = count

    return result

# Test cases to verify the function works as expected
print(histogram('a b c'))  # Output: {}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output: {}
